import json, math, re, sys, importlib.util
from collections import Counter
RUN='/workspace/runs/744847db7fd315003a566e3a01a1e6bc23bc8c66'
spec = importlib.util.spec_from_file_location("mem", "/workspace/harness/solver/tools/memory.py")
M = importlib.util.module_from_spec(spec); spec.loader.exec_module(M)
val=json.load(open('/tmp/evo12/val.json'))

def load(task):
    M.MEMORY_PATH=f'{RUN}/{task}/memory.json'
    return M.load_examples()

def norm(s):
    s=str(s).lower().strip(); s=re.sub(r'\s+',' ',s); return re.sub(r'[.!?]+$','',s)

def grams(text, n):
    text=" ".join(str(text).split()).lower()
    return [text[i:i+n] for i in range(max(0,len(text)-n+1))]

def reaction_type(text):
    m=re.search(r'reaction type is ([^.\n]+)', str(text))
    return m.group(1).strip().lower() if m else None

class R:
    """Flexible ranker for the grid: ngram size, shared-df cut, idf on/off, tf sublinear, field."""
    def __init__(self, examples, n=3, dfcut=0.5, idf=True, sublinear=False, field='input'):
        self.n=n; self.idf_on=idf; self.sub=sublinear
        self.vectors=[Counter(grams(e.get(field) or e['input'], n)) for e in examples]
        freq=Counter()
        for v in self.vectors: freq.update(v.keys())
        total=len(examples) or 1
        self.shared={g for g,c in freq.items() if c>=dfcut*total} if dfcut<1 else set()
        self.idf={g: (math.log((total+1)/(c+1))+1.0 if idf else 1.0) for g,c in freq.items()}
        def w(count, g): return (1+math.log(count) if sublinear and count>0 else count)*self.idf.get(g,0.0)
        self.norms=[math.sqrt(sum(w(c,g)**2 for g,c in v.items() if g not in self.shared)) or 1.0 for v in self.vectors]
    def rank(self, query, field_query=None):
        q=Counter(grams(query, self.n))
        def w(count,g): return (1+math.log(count) if self.sub and count>0 else count)*self.idf.get(g,1.0)
        grams_q={g:c for g,c in q.items() if g not in self.shared}
        norm=math.sqrt(sum((self.idf.get(g,1.0)*c)**2 for g,c in grams_q.items())) or 1.0
        scored=[(sum(w(c,g)*grams_q[g] for g,c in v.items() if g in grams_q)/(norm*self.norms[i]), i)
                for i,v in enumerate(self.vectors)]
        scored.sort(key=lambda p:(-p[0],p[1]))
        return [i for _,i in scored]

def evaluate(label, **kw):
    res={}
    for task in ['Symptom2Disease','LawBench','USPTO']:
        ex=load(task); r=R(ex, **kw)
        t1=t5=t100=rt1=rt5=tot=0
        for v in val[task]:
            order=r.rank(v['input']); tot+=1
            labs=[norm(ex[i]['target']) for i in order]
            if labs[0]==norm(v['target']): t1+=1
            if norm(v['target']) in labs[:5]: t5+=1
            if norm(v['target']) in labs[:100]: t100+=1
            qt=reaction_type(v['input'])
            if qt:
                rt=[reaction_type(ex[i]['input']) for i in order[:5]]
                if rt and rt[0]==qt: rt1+=1
                if qt in rt: rt5+=1
        res[task]=(t1,t5,t100,rt1,rt5,tot)
    print(f'{label:38s} ' + ' | '.join(f'{k[:4]} t1={v[0]} t5={v[1]} t100={v[2]}' for k,v in res.items()), flush=True)
    return res

if __name__=='__main__':
    evaluate('base n3 df.5 idf')
    for n in (2,4,5):
        evaluate(f'n{n} df.5 idf', n=n)
    for d in (0.2,0.35,0.7,1.0):
        evaluate(f'n3 df{d} idf', dfcut=d)
    evaluate('n3 df.5 noidf', idf=False)
    evaluate('n3 df.5 sublinear', sublinear=True)
    evaluate('n4 df.35 idf', n=4, dfcut=0.35)
    evaluate('n2 df.35 idf', n=2, dfcut=0.35)
