        print(f'   q{k[0]:02d} s{k[1]} {"GAIN" if b[k]["ok"] else "LOSS"}: target={a[k]["tgt"]}')
        print(f'      parent   pred={a[k]["pred"]!r} first={a[k]["first"]!r}')
        print(f'      candidate pred={b[k]["pred"]!r} first={b[k]["first"]!r}')
        print(f'      listing top-30 identical: {same_set}')
EOF
